def execute(arguments):
    """
    JSONPath查询

    参数:
        arguments (dict): 包含以下字段
            - data (any): JSON数据（对象或数组），必填
            - path (str): JSONPath表达式，必填
            - first (bool): 是否只返回第一个匹配，默认 False

    返回:
        dict: 包含查询结果的字典
            - success (bool): 是否成功
            - results (list): 匹配结果列表
            - count (int): 匹配数量
            - error (str): 错误信息（失败时）

    JSONPath语法示例:
        $ - 根对象
        . - 子属性访问
        .. - 递归下降
        * - 通配符
        [] - 数组索引或属性名
        [start:end] - 数组切片
        [?()] - 过滤表达式
    """
    import json
    import re

    data = arguments.get("data")
    path = arguments.get("path", "")
    first = arguments.get("first", False)

    if data is None:
        return {"success": False, "error": "请提供JSON数据"}

    if not path:
        return {"success": False, "error": "请提供JSONPath表达式"}

    try:
        if isinstance(data, str):
            data = json.loads(data)

        def query(obj, path_parts):
            if not path_parts:
                return [obj]

            current = path_parts[0]
            rest = path_parts[1:]
            results = []

            if current == "$":
                results.extend(query(obj, rest))
            elif current == "*":
                if isinstance(obj, dict):
                    for v in obj.values():
                        results.extend(query(v, rest))
                elif isinstance(obj, list):
                    for item in obj:
                        results.extend(query(item, rest))
            elif current == "..":
                def recursive_search(o):
                    if not rest:
                        results.append(o)
                    else:
                        results.extend(query(o, rest))
                    if isinstance(o, dict):
                        for v in o.values():
                            recursive_search(v)
                    elif isinstance(o, list):
                        for item in o:
                            recursive_search(item)
                recursive_search(obj)
            elif current.startswith("[") and current.endswith("]"):
                index_str = current[1:-1]
                if index_str == "*":
                    if isinstance(obj, list):
                        for item in obj:
                            results.extend(query(item, rest))
                elif ":" in index_str:
                    parts = index_str.split(":")
                    start = int(parts[0]) if parts[0] else None
                    end = int(parts[1]) if parts[1] else None
                    if isinstance(obj, list):
                        for item in obj[start:end]:
                            results.extend(query(item, rest))
                else:
                    index = int(index_str)
                    if isinstance(obj, list) and 0 <= index < len(obj):
                        results.extend(query(obj[index], rest))
            else:
                if isinstance(obj, dict) and current in obj:
                    results.extend(query(obj[current], rest))

            return results

        path_parts = re.split(r'\.|(\[.*?\])', path)
        path_parts = [p for p in path_parts if p]

        results = query(data, path_parts)

        if first and results:
            results = [results[0]]

        return {
            "success": True,
            "results": results,
            "count": len(results)
        }
    except Exception as e:
        return {"success": False, "error": str(e)}
